mapper.select:
select distinct t.dict_id, t.dict_type, t.dict_name, t.component_info, r.app_id, r.app_id as tenant_id, tn.company_name as tenant_name, tn.company_name as app_name from sys_dict_type t join sys_dict_type_app r on r.dict_id = t.dict_id join ( select app_id as tenant_id, max(app_name) as company_name from sys_application where del_flag = '0' group by app_id ) tn on tn.tenant_id = r.app_id where t.category_type = 'role'
and r.app_id = #{tenantId}
order by r.app_id, t.dict_id

select v.dict_id, t.dict_type, t.dict_name, t.component_info, v.app_id, v.app_id as tenant_id, v.field_key, v.field_value from sys_role_dict_value v join sys_dict_type t on t.dict_id = v.dict_id where v.role_id = #{roleId} and v.field_value is not null and v.field_value != ''
and v.app_id = #{tenantId}
order by v.dict_id
